import { localPrice } from "./impl.ts";

function expect(usdCents, currency, rate) {
  const divisor = currency === "JPY" ? 100 : 1;
  // exact via decimal text, independent copy
  const dec = (value) => {
    const negative = value < 0;
    const [body, expRaw] = Math.abs(value).toString().toLowerCase().split("e");
    const exp = expRaw ? Number(expRaw) : 0;
    const [whole, frac = ""] = body.split(".");
    const num = BigInt(whole + frac) * (negative ? -1n : 1n);
    const scale = frac.length - exp;
    if (scale >= 0) return { num, den: 10n ** BigInt(scale) };
    return { num: num * 10n ** BigInt(-scale), den: 1n };
  };
  const a = dec(usdCents), b = dec(rate);
  const num = a.num * b.num;
  const den = a.den * b.den * BigInt(divisor);
  const negative = num < 0n;
  const absNum = negative ? -num : num;
  const q = absNum / den;
  const r = absNum % den;
  const rounded = r * 2n >= den ? q + 1n : q;
  return Number(negative ? -rounded : rounded);
}

const rates = [0.92, 1, 1.005, 0.78, 150, 149.5, 0.999, 1.1, 0.3, 156.789, 0.0001, 1e-7, 1.23e4, 9.99];
const cents = [0, 1, 2, 5, 10, 49, 50, 99, 100, 101, 999, 1000, 1999, 123456, -100, -1];
const currencies = ["USD", "EUR", "GBP", "JPY"];
let n = 0, bad = 0;
for (const currency of currencies) for (const usdCents of cents) for (const rate of rates) {
  const got = localPrice({ id: "p", usdCents, currency, rate }).amountMinor;
  const want = expect(usdCents, currency, rate);
  n++;
  if (got !== want) { bad++; console.log("mismatch", {currency, usdCents, rate, got, want}); }
}
console.log({n, bad});

// binary float disagreement sample should be the corrected one
const tricky = localPrice({ id: "t", usdCents: 100, currency: "EUR", rate: 1.005 });
console.log("tricky", tricky, "mathround", Math.round(100 * 1.005));
'
